import{_ as d,a0 as p,w as l,s as a,ao as i,I as e,a1 as s,A as n,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Root 是谁？为什么会有 Root 账户？ | LCTT x X-CMD","titleTemplate":false,"description":"Root 是谁？为什么会有 Root 账户？ | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Root 是谁？为什么会有 Root 账户？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Root 是谁？为什么会有 Root 账户？ | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170211 Who Is Root Why Does Root Exist","title":"Root 是谁？为什么会有 Root 账户？","tag":"201702","desc":""},"relativePath":"201702/20170211 Who Is Root Why Does Root Exist.md","filePath":"[post].md"}'),u={name:"201702/20170211 Who Is Root Why Does Root Exist.md"};function m(w,o,f,x,T,h){const r=p("Link");return l(),a("div",null,[o[25]||(o[25]=i('<h1 id="root-是谁-为什么会有-root-账户" tabindex="-1">Root 是谁？为什么会有 Root 账户？ <a class="header-anchor" href="#root-是谁-为什么会有-root-账户" aria-label="Permalink to “Root 是谁？为什么会有 Root 账户？”">​</a></h1><p>在 Linux 中为什么会有一个名为 root 的特定账户？该怎么使用 root 账户？它在哪些场景下必须使用，哪些场景下不能使用？对于以上几个问题，如果您感兴趣的话，那么请继续阅读。</p><p>本文中，我们提供了一些关于 root 账户的参考资料，方便您了解。</p><h3 id="root-是什么" tabindex="-1">root 是什么？ <a class="header-anchor" href="#root-是什么" aria-label="Permalink to “root 是什么？”">​</a></h3><p>首先，记住这一点，在 Unix 类操作系统中，目录的层级结构被设计为树状结构。起始目录是一个特殊目录，使用斜杠 <code>/</code> 表示，而其他目录都是由起始目录分支而来。由于这种结构很像现实中的树，所以 <code>/</code> 也被称为根（root）目录。</p><p>下图，我们可以看到以下命令的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -d / | less</span></span></code></pre></div><p>该命令主要是演示一下 <code>/</code> 根目录和树<code>根</code>的类比。</p>',8)),e("p",null,[s(r,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Linux-root-Directory-Tree.png"},{default:n(()=>[...o[0]||(o[0]=[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Linux-root-Directory-Tree.png",alt:"Linux 的目录层级"},null,-1)])]),_:1})]),o[26]||(o[26]=i('<p><em>Linux 的目录层级</em></p><p>虽然 root 账户命名的原因还不是很清楚，可能是因为 root 账户是唯一一个在根目录 <code>/</code> 中有写权限的账号吧。</p><p>此外，由于 root 账户可以访问 Unix 类操作系统中的所有文件和命令，因此，它也常被称为超级用户。</p><p>另外，根目录 <code>/</code> 和 <code>/root</code> 目录不能混淆了，<code>/root</code> 目录是 <code>root</code> 账户的家目录。实际上，<code>/root</code> 目录是根目录 <code>/</code> 的子目录。</p><h3 id="获取-root-权限" tabindex="-1">获取 root 权限 <a class="header-anchor" href="#获取-root-权限" aria-label="Permalink to “获取 root 权限”">​</a></h3><p>当我们说到 root（或者超级用户）权限的时候，我们指的是这样一种账户的权限：其在系统上的权限包含（但不限于）修改系统并授权其他用户对系统资源的访问权限。</p><p>胡乱使用 root 账户，轻则系统崩溃重则系统完全故障。这就是为什么会说，以下准则是使用 root 账户的正确姿势：</p><p>首先，使用 root 账户运行 <code>visudo</code> 命令编辑 <code>/etc/sudoers</code> 文件，给指定账户（如：<code>supervisor</code>）授予最低的超级用户权限。</p>',8)),e("p",null,[o[3]||(o[3]=t("最低超级用户权限可以包含，例如：",-1)),s(r,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:n(()=>[...o[1]||(o[1]=[t("添加用户 (",-1),e("code",null,"adduser",-1),t(")",-1)])]),_:1}),o[4]||(o[4]=t("、",-1)),s(r,{href:"http://www.tecmint.com/usermod-command-examples/"},{default:n(()=>[...o[2]||(o[2]=[t("修改用户 (",-1),e("code",null,"usermod",-1),t(")",-1)])]),_:1}),o[5]||(o[5]=t("等权限。",-1))]),e("p",null,[o[7]||(o[7]=t("接着，使用 ",-1)),o[8]||(o[8]=e("code",null,"supervisor",-1)),o[9]||(o[9]=t(" 账户登录并",-1)),s(r,{href:"http://www.tecmint.com/sudoers-configurations-for-setting-sudo-in-linux/"},{default:n(()=>[...o[6]||(o[6]=[t("使用 ",-1),e("code",null,"sudo",-1),t(" 执行用户管理任务",-1)])]),_:1}),o[10]||(o[10]=t("。此时，你可能会发现，当你执行需要超级用户权限（例如：删除软件包）的其它任务时，会失败。",-1))]),e("p",null,[s(r,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Run-Commands-Without-sudo.png"},{default:n(()=>[...o[11]||(o[11]=[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Run-Commands-Without-sudo.png",alt:"没有使用超级用户权限运行命令"},null,-1)])]),_:1})]),o[27]||(o[27]=i('<p><em>没有使用超级用户权限运行命令</em></p><p>在必须使用超级用户权限时，重复执行以上两个步骤，一旦执行完成，则立即使用 <code>exit</code> 命令退回到无特限的账户。</p><p>此时，你需要确定一下其他周期性的任务是否需要超级用户权限？如果需要，那么在 <code>/etc/sudoers</code> 中，给指定的账户或组授予必要的权限，尽量避免直接使用 <code>root</code> 账户操作。</p><h5 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h5><p>本文可以作为在 Unix 类操作系统中正确使用 root 账户的简单参考。收藏一下，你就可以随时翻阅！</p><p>还是一样，如果您对本文有什么疑问或建议，请使用以下的评论表单给我们评论留言，期待您的回音！</p><hr><p>作者简介：</p><p>Gabriel Cánepa 来自 Villa Mercedes, San Luis, Argentina。他是一名 GNU/Linux 系统管理员和 Web 开发员，现在一家全球领先的消费品公司就职。他很喜欢使用 FOSS 工具来提高自己的工作效率。</p><hr>',10)),e("p",null,[o[13]||(o[13]=t("via: ",-1)),s(r,{href:"http://www.tecmint.com/who-is-root-why-does-root-exist-in-linux/"},{default:n(()=>[...o[12]||(o[12]=[t("http://www.tecmint.com/who-is-root-why-does-root-exist-in-linux/",-1)])]),_:1})]),e("p",null,[o[17]||(o[17]=t("作者：",-1)),s(r,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...o[14]||(o[14]=[t("Gabriel Cánepa",-1)])]),_:1}),o[18]||(o[18]=t(" 译者：",-1)),s(r,{href:"https://github.com/zhb127"},{default:n(()=>[...o[15]||(o[15]=[t("zhb127",-1)])]),_:1}),o[19]||(o[19]=t(" 校对：",-1)),s(r,{href:"https://github.com/wxy"},{default:n(()=>[...o[16]||(o[16]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原创编译，",-1)),s(r,{href:"https://linux.cn/"},{default:n(()=>[...o[21]||(o[21]=[t("Linux中国",-1)])]),_:1}),o[24]||(o[24]=t(" 荣誉推出",-1))])])}const b=d(u,[["render",m]]);export{C as __pageData,b as default};
